function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const length = size === 'large' ? 9 : 1 + pick(5);
  // Sometimes draw from a small pool of digits (such as 1, 2, 4, 8) that often divide the number.
  const pools = [[1, 2, 3, 4, 5, 6, 7, 8, 9], [1, 2, 4, 8], [1, 3, 9], [1, 2, 5]];
  const pool = pools[pick(pools.length)];
  let num = 0;
  for (let i = 0; i < length; i++) num = num * 10 + pool[pick(pool.length)];
  return [num];
}
